package dev.kalarianathecila.schoolStuff.tutelini;

import javax.swing.*;
import java.awt.*;
import java.net.URL;
import java.util.concurrent.ThreadLocalRandom;
import com.formdev.flatlaf.FlatDarkLaf;

public class Draw extends JFrame {
    private static final int MIN_SPIN_DELAY_MS = 20_000;
    private static final int MAX_SPIN_DELAY_MS = 60_000;
    private static final int SPIN_FRAME_DELAY_MS = 180;
    private static final String[] TURTLE_ICON_PATHS = {
            "/dev/kalarianathecila/schoolStuff/tutelini/tutel.png",
            "/dev/kalarianathecila/schoolStuff/tutelini/tutel_90.png",
            "/dev/kalarianathecila/schoolStuff/tutelini/tutel_180.png",
            "/dev/kalarianathecila/schoolStuff/tutelini/tutel_270.png"
    };

    private Image[] turtleIcons;
    private int currentIconIndex;
    private int loadedIconCount;
    private boolean isSpinning;

    public static void main(String[] args) {
        FlatDarkLaf.setup();
        DrawSelection selection = readSelection(args);

        SwingUtilities.invokeLater(() -> {
            Draw app = new Draw();

            app.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            app.setSize(1920, 1080);

            app.initializeIconRotation();

            app.add(new MainPanel(selection.scale, selection.target));
            app.setVisible(true);
            app.scheduleNextIconSpin();
        });
    }

    private void initializeIconRotation() {
        this.turtleIcons = new Image[TURTLE_ICON_PATHS.length];

        for (int i = 0; i < TURTLE_ICON_PATHS.length; i++) {
            URL iconUrl = Draw.class.getResource(TURTLE_ICON_PATHS[i]);
            if (iconUrl != null) {
                turtleIcons[i] = new ImageIcon(iconUrl).getImage();
            }
        }

        loadedIconCount = 0;
        for (Image turtleIcon : turtleIcons) {
            if (turtleIcon != null) {
                loadedIconCount++;
            }
        }

        currentIconIndex = 0;
        isSpinning = false;
        if (turtleIcons[currentIconIndex] != null) {
            setIconImage(turtleIcons[currentIconIndex]);
        }
    }

    private void scheduleNextIconSpin() {
        int delay = ThreadLocalRandom.current().nextInt(MIN_SPIN_DELAY_MS, MAX_SPIN_DELAY_MS + 1);
        Timer timer = new Timer(delay, e -> startSpinAnimation());
        timer.setRepeats(false);
        timer.start();
    }

    private void startSpinAnimation() {
        if (isSpinning || turtleIcons == null || loadedIconCount < 2) {
            scheduleNextIconSpin();
            return;
        }

        isSpinning = true;
        final int[] completedSteps = {0};
        final int stepsForFullSpin = loadedIconCount;

        Timer animationTimer = new Timer(SPIN_FRAME_DELAY_MS, e -> {
            if (!advanceToNextAvailableIcon()) {
                ((Timer) e.getSource()).stop();
                isSpinning = false;
                scheduleNextIconSpin();
                return;
            }

            completedSteps[0]++;
            if (completedSteps[0] >= stepsForFullSpin) {
                ((Timer) e.getSource()).stop();
                isSpinning = false;
                scheduleNextIconSpin();
            }
        });
        animationTimer.start();
    }

    private boolean advanceToNextAvailableIcon() {
        if (turtleIcons == null || turtleIcons.length == 0) {
            return false;
        }

        for (int i = 0; i < turtleIcons.length; i++) {
            currentIconIndex = (currentIconIndex + 1) % turtleIcons.length;
            if (turtleIcons[currentIconIndex] != null) {
                setIconImage(turtleIcons[currentIconIndex]);
                return true;
            }
        }

        return false;
    }

    private static DrawSelection readSelection(String[] args) {
        Integer argScale = null;
        MainPanel.DrawingTarget argTarget = MainPanel.DrawingTarget.HOUSE;

        if (args != null && args.length > 0) {
            argScale = parseScale(args[0]);
        }

        if (args != null && args.length > 1) {
            argTarget = parseTarget(args[1]);
        }

        JTextField scaleField = new JTextField(String.valueOf(argScale != null ? argScale : 1), 8);
        JCheckBox houseCheck = new JCheckBox("House (value = scale)", argTarget == MainPanel.DrawingTarget.HOUSE);
        JCheckBox treeCheck = new JCheckBox("Tree (value = levels)", argTarget == MainPanel.DrawingTarget.TREE);
        JCheckBox yTreeCheck = new JCheckBox("Y-Tree (value = levels)", argTarget == MainPanel.DrawingTarget.Y_TREE);
        JCheckBox kochCheck = new JCheckBox("Koch Snowflake (value = levels)", argTarget == MainPanel.DrawingTarget.KOCH_SNOWFLAKE);
        JCheckBox sierpinskiCheck = new JCheckBox("Sierpinski Triangle (value = levels)", argTarget == MainPanel.DrawingTarget.SIERPINSKI_TRIANGLE);
        JCheckBox dragonCheck = new JCheckBox("Dragon Curve (value = levels)", argTarget == MainPanel.DrawingTarget.DRAGON_CURVE);

        ButtonGroup group = new ButtonGroup();
        group.add(houseCheck);
        group.add(treeCheck);
        group.add(yTreeCheck);
        group.add(kochCheck);
        group.add(sierpinskiCheck);
        group.add(dragonCheck);

        JPanel standardPanel = new JPanel(new GridLayout(0, 1, 0, 4));
        standardPanel.setBorder(BorderFactory.createTitledBorder("Standard"));
        standardPanel.add(houseCheck);

        JPanel fractalPanel = new JPanel(new GridLayout(0, 1, 0, 4));
        fractalPanel.setBorder(BorderFactory.createTitledBorder("Fractals"));
        fractalPanel.add(treeCheck);
        fractalPanel.add(yTreeCheck);
        fractalPanel.add(kochCheck);
        fractalPanel.add(sierpinskiCheck);
        fractalPanel.add(dragonCheck);

        JPanel panel = new JPanel(new GridLayout(0, 1, 0, 6));
        panel.add(new JLabel("Enter value (positive integer):"));
        panel.add(scaleField);
        panel.add(new JLabel("Fractals use level caps for stability (tree 12, y-tree 12, koch 6, sierpinski 7, dragon 16)."));
        panel.add(new JLabel("Apply value to:"));
        panel.add(standardPanel);
        panel.add(fractalPanel);

        while (true) {
            int result = JOptionPane.showConfirmDialog(
                    null,
                    panel,
                    "Draw Settings",
                    JOptionPane.OK_CANCEL_OPTION,
                    JOptionPane.QUESTION_MESSAGE
            );

            if (result != JOptionPane.OK_OPTION) {
                return new DrawSelection(argScale != null ? argScale : 1, argTarget);
            }

            Integer parsedScale = parseScale(scaleField.getText());
            if (parsedScale == null) {
                JOptionPane.showMessageDialog(
                        null,
                        "Please enter a positive integer.",
                        "Invalid Value",
                        JOptionPane.WARNING_MESSAGE
                );
                continue;
            }

            MainPanel.DrawingTarget target = treeCheck.isSelected()
                    ? MainPanel.DrawingTarget.TREE
                    : yTreeCheck.isSelected()
                    ? MainPanel.DrawingTarget.Y_TREE
                    : kochCheck.isSelected()
                    ? MainPanel.DrawingTarget.KOCH_SNOWFLAKE
                    : sierpinskiCheck.isSelected()
                    ? MainPanel.DrawingTarget.SIERPINSKI_TRIANGLE
                    : dragonCheck.isSelected()
                    ? MainPanel.DrawingTarget.DRAGON_CURVE
                    : MainPanel.DrawingTarget.HOUSE;

            return new DrawSelection(parsedScale, target);
        }
    }

    private static Integer parseScale(String value) {
        if (value == null) {
            return null;
        }

        try {
            int parsed = Integer.parseInt(value.trim());
            return parsed > 0 ? parsed : null;
        } catch (NumberFormatException ignored) {
            return null;
        }
    }

    private static MainPanel.DrawingTarget parseTarget(String value) {
        if (value == null) {
            return MainPanel.DrawingTarget.HOUSE;
        }

        String normalized = value.trim().toLowerCase();
        if ("tree".equals(normalized)) {
            return MainPanel.DrawingTarget.TREE;
        }
        if ("y-tree".equals(normalized) || "ytree".equals(normalized) || "y_tree".equals(normalized)) {
            return MainPanel.DrawingTarget.Y_TREE;
        }
        if ("koch".equals(normalized) || "snowflake".equals(normalized) || "koch_snowflake".equals(normalized)) {
            return MainPanel.DrawingTarget.KOCH_SNOWFLAKE;
        }
        if ("sierpinski".equals(normalized) || "triangle".equals(normalized) || "sierpinski_triangle".equals(normalized)) {
            return MainPanel.DrawingTarget.SIERPINSKI_TRIANGLE;
        }
        if ("dragon".equals(normalized) || "dragon_curve".equals(normalized)) {
            return MainPanel.DrawingTarget.DRAGON_CURVE;
        }

        return MainPanel.DrawingTarget.HOUSE;
    }

    private static class DrawSelection {
        private final int scale;
        private final MainPanel.DrawingTarget target;

        private DrawSelection(int scale, MainPanel.DrawingTarget target) {
            this.scale = scale;
            this.target = target;
        }
    }
}

package dev.kalarianathecila.schoolStuff.tutelini;

import javax.swing.*;
import java.awt.*;
import java.net.URL;
import java.util.concurrent.ThreadLocalRandom;
import com.formdev.flatlaf.FlatDarkLaf;

public class Draw extends JFrame {
    private static final int MIN_SPIN_DELAY_MS = 20_000;
    private static final int MAX_SPIN_DELAY_MS = 60_000;
    private static final int SPIN_FRAME_DELAY_MS = 180;
    private static final double ANGLE_STEP_DEGREES = 1.0;
    private static final double LENGTH_STEP = 0.05;
    private static final String[] TURTLE_ICON_PATHS = {
            "/dev/kalarianathecila/schoolStuff/tutelini/tutel.png",
            "/dev/kalarianathecila/schoolStuff/tutelini/tutel_90.png",
            "/dev/kalarianathecila/schoolStuff/tutelini/tutel_180.png",
            "/dev/kalarianathecila/schoolStuff/tutelini/tutel_270.png"
    };

    private Image[] turtleIcons;
    private int currentIconIndex;
    private int loadedIconCount;
    private boolean isSpinning;

    public static void main(String[] args) {
        FlatDarkLaf.setup();
        DrawSelection selection = readSelection(args);

        SwingUtilities.invokeLater(() -> {
            Draw app = new Draw();

            app.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            app.setSize(1920, 1080);

            app.initializeIconRotation();

            MainPanel mainPanel = new MainPanel(selection.scale, selection.target);
            app.add(mainPanel);
            app.installTreeControls(mainPanel);
            app.setVisible(true);
            app.refreshTreeControlTitle(mainPanel);
            app.scheduleNextIconSpin();
        });
    }

    private void installTreeControls(MainPanel mainPanel) {
        JRootPane rootPane = getRootPane();
        InputMap inputMap = rootPane.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW);
        ActionMap actionMap = rootPane.getActionMap();

        inputMap.put(KeyStroke.getKeyStroke("LEFT"), "tree-angle-dec");
        inputMap.put(KeyStroke.getKeyStroke("RIGHT"), "tree-angle-inc");
        inputMap.put(KeyStroke.getKeyStroke("UP"), "tree-length-inc");
        inputMap.put(KeyStroke.getKeyStroke("DOWN"), "tree-length-dec");

        actionMap.put("tree-angle-dec", new AbstractAction() {
            @Override
            public void actionPerformed(java.awt.event.ActionEvent e) {
                mainPanel.adjustTreeAngle(-ANGLE_STEP_DEGREES);
                refreshTreeControlTitle(mainPanel);
            }
        });

        actionMap.put("tree-angle-inc", new AbstractAction() {
            @Override
            public void actionPerformed(java.awt.event.ActionEvent e) {
                mainPanel.adjustTreeAngle(ANGLE_STEP_DEGREES);
                refreshTreeControlTitle(mainPanel);
            }
        });

        actionMap.put("tree-length-inc", new AbstractAction() {
            @Override
            public void actionPerformed(java.awt.event.ActionEvent e) {
                mainPanel.adjustTreeLengthMultiplier(LENGTH_STEP);
                refreshTreeControlTitle(mainPanel);
            }
        });

        actionMap.put("tree-length-dec", new AbstractAction() {
            @Override
            public void actionPerformed(java.awt.event.ActionEvent e) {
                mainPanel.adjustTreeLengthMultiplier(-LENGTH_STEP);
                refreshTreeControlTitle(mainPanel);
            }
        });
    }

    private void refreshTreeControlTitle(MainPanel mainPanel) {
        setTitle(String.format(
                "Draw | <-/-> angle: %.1f deg | Up/Down length: %.2fx",
                mainPanel.getTreeAngleOffset(),
                mainPanel.getTreeLengthMultiplier()
        ));
    }

    private void initializeIconRotation() {
        this.turtleIcons = new Image[TURTLE_ICON_PATHS.length];

        for (int i = 0; i < TURTLE_ICON_PATHS.length; i++) {
            URL iconUrl = Draw.class.getResource(TURTLE_ICON_PATHS[i]);
            if (iconUrl != null) {
                turtleIcons[i] = new ImageIcon(iconUrl).getImage();
            }
        }

        loadedIconCount = 0;
        for (Image turtleIcon : turtleIcons) {
            if (turtleIcon != null) {
                loadedIconCount++;
            }
        }

        currentIconIndex = 0;
        isSpinning = false;
        if (turtleIcons[currentIconIndex] != null) {
            setIconImage(turtleIcons[currentIconIndex]);
        }
    }

    private void scheduleNextIconSpin() {
        int delay = ThreadLocalRandom.current().nextInt(MIN_SPIN_DELAY_MS, MAX_SPIN_DELAY_MS + 1);
        Timer timer = new Timer(delay, e -> startSpinAnimation());
        timer.setRepeats(false);
        timer.start();
    }

    private void startSpinAnimation() {
        if (isSpinning || turtleIcons == null || loadedIconCount < 2) {
            scheduleNextIconSpin();
            return;
        }

        isSpinning = true;
        final int[] completedSteps = {0};
        final int stepsForFullSpin = loadedIconCount;

        Timer animationTimer = new Timer(SPIN_FRAME_DELAY_MS, e -> {
            if (!advanceToNextAvailableIcon()) {
                ((Timer) e.getSource()).stop();
                isSpinning = false;
                scheduleNextIconSpin();
                return;
            }

            completedSteps[0]++;
            if (completedSteps[0] >= stepsForFullSpin) {
                ((Timer) e.getSource()).stop();
                isSpinning = false;
                scheduleNextIconSpin();
            }
        });
        animationTimer.start();
    }

    private boolean advanceToNextAvailableIcon() {
        if (turtleIcons == null || turtleIcons.length == 0) {
            return false;
        }

        for (int i = 0; i < turtleIcons.length; i++) {
            currentIconIndex = (currentIconIndex + 1) % turtleIcons.length;
            if (turtleIcons[currentIconIndex] != null) {
                setIconImage(turtleIcons[currentIconIndex]);
                return true;
            }
        }

        return false;
    }

    private static DrawSelection readSelection(String[] args) {
        Integer argScale = null;
        MainPanel.DrawingTarget argTarget = MainPanel.DrawingTarget.HOUSE;

        if (args != null && args.length > 0) {
            argScale = parseScale(args[0]);
        }

        if (args != null && args.length > 1) {
            argTarget = parseTarget(args[1]);
        }

        JTextField scaleField = new JTextField(String.valueOf(argScale != null ? argScale : 1), 8);
        JCheckBox houseCheck = new JCheckBox("House (value = scale)", argTarget == MainPanel.DrawingTarget.HOUSE);
        JCheckBox treeCheck = new JCheckBox("Tree (value = levels)", argTarget == MainPanel.DrawingTarget.TREE);
        JCheckBox yTreeCheck = new JCheckBox("Y-Tree (value = levels)", argTarget == MainPanel.DrawingTarget.Y_TREE);
        JCheckBox kochCheck = new JCheckBox("Koch Snowflake (value = levels)", argTarget == MainPanel.DrawingTarget.KOCH_SNOWFLAKE);
        JCheckBox sierpinskiCheck = new JCheckBox("Sierpinski Triangle (value = levels)", argTarget == MainPanel.DrawingTarget.SIERPINSKI_TRIANGLE);
        JCheckBox dragonCheck = new JCheckBox("Dragon Curve (value = levels)", argTarget == MainPanel.DrawingTarget.DRAGON_CURVE);

        ButtonGroup group = new ButtonGroup();
        group.add(houseCheck);
        group.add(treeCheck);
        group.add(yTreeCheck);
        group.add(kochCheck);
        group.add(sierpinskiCheck);
        group.add(dragonCheck);

        JPanel standardPanel = new JPanel(new GridLayout(0, 1, 0, 4));
        standardPanel.setBorder(BorderFactory.createTitledBorder("Standard"));
        standardPanel.add(houseCheck);

        JPanel fractalPanel = new JPanel(new GridLayout(0, 1, 0, 4));
        fractalPanel.setBorder(BorderFactory.createTitledBorder("Fractals"));
        fractalPanel.add(treeCheck);
        fractalPanel.add(yTreeCheck);
        fractalPanel.add(kochCheck);
        fractalPanel.add(sierpinskiCheck);
        fractalPanel.add(dragonCheck);

        JPanel panel = new JPanel(new GridLayout(0, 1, 0, 6));
        panel.add(new JLabel("Enter value (positive integer):"));
        panel.add(scaleField);
        panel.add(new JLabel("Fractals use level caps for stability (tree 12, y-tree 12, koch 6, sierpinski 7, dragon 16)."));
        panel.add(new JLabel("Apply value to:"));
        panel.add(standardPanel);
        panel.add(fractalPanel);

        while (true) {
            int result = JOptionPane.showConfirmDialog(
                    null,
                    panel,
                    "Draw Settings",
                    JOptionPane.OK_CANCEL_OPTION,
                    JOptionPane.QUESTION_MESSAGE
            );

            if (result != JOptionPane.OK_OPTION) {
                return new DrawSelection(argScale != null ? argScale : 1, argTarget);
            }

            Integer parsedScale = parseScale(scaleField.getText());
            if (parsedScale == null) {
                JOptionPane.showMessageDialog(
                        null,
                        "Please enter a positive integer.",
                        "Invalid Value",
                        JOptionPane.WARNING_MESSAGE
                );
                continue;
            }

            MainPanel.DrawingTarget target = treeCheck.isSelected()
                    ? MainPanel.DrawingTarget.TREE
                    : yTreeCheck.isSelected()
                    ? MainPanel.DrawingTarget.Y_TREE
                    : kochCheck.isSelected()
                    ? MainPanel.DrawingTarget.KOCH_SNOWFLAKE
                    : sierpinskiCheck.isSelected()
                    ? MainPanel.DrawingTarget.SIERPINSKI_TRIANGLE
                    : dragonCheck.isSelected()
                    ? MainPanel.DrawingTarget.DRAGON_CURVE
                    : MainPanel.DrawingTarget.HOUSE;

            return new DrawSelection(parsedScale, target);
        }
    }

    private static Integer parseScale(String value) {
        if (value == null) {
            return null;
        }

        try {
            int parsed = Integer.parseInt(value.trim());
            return parsed > 0 ? parsed : null;
        } catch (NumberFormatException ignored) {
            return null;
        }
    }

    private static MainPanel.DrawingTarget parseTarget(String value) {
        if (value == null) {
            return MainPanel.DrawingTarget.HOUSE;
        }

        String normalized = value.trim().toLowerCase();
        if ("tree".equals(normalized)) {
            return MainPanel.DrawingTarget.TREE;
        }
        if ("y-tree".equals(normalized) || "ytree".equals(normalized) || "y_tree".equals(normalized)) {
            return MainPanel.DrawingTarget.Y_TREE;
        }
        if ("koch".equals(normalized) || "snowflake".equals(normalized) || "koch_snowflake".equals(normalized)) {
            return MainPanel.DrawingTarget.KOCH_SNOWFLAKE;
        }
        if ("sierpinski".equals(normalized) || "triangle".equals(normalized) || "sierpinski_triangle".equals(normalized)) {
            return MainPanel.DrawingTarget.SIERPINSKI_TRIANGLE;
        }
        if ("dragon".equals(normalized) || "dragon_curve".equals(normalized)) {
            return MainPanel.DrawingTarget.DRAGON_CURVE;
        }

        return MainPanel.DrawingTarget.HOUSE;
    }

    private static class DrawSelection {
        private final int scale;
        private final MainPanel.DrawingTarget target;

        private DrawSelection(int scale, MainPanel.DrawingTarget target) {
            this.scale = scale;
            this.target = target;
        }
    }
}

package dev.kalarianathecila.schoolStuff.tutelini;

import java.awt.*;

public class MainPanel extends Panel {
    private static final int MAX_TREE_LEVELS = 12;
    private static final int MAX_Y_TREE_LEVELS = 12;
    private static final int MAX_KOCH_LEVELS = 6;
    private static final int MAX_SIERPINSKI_LEVELS = 7;
    private static final int MAX_DRAGON_LEVELS = 16;

    private static final double BINARY_BRANCH_ANGLE = 30.0;
    private static final double BINARY_BRANCH_SCALE = 0.7;
    private static final double Y_BRANCH_ANGLE = 35.0;
    private static final double Y_BRANCH_SCALE = 0.72;

    public enum DrawingTarget {
        HOUSE,
        TREE,
        Y_TREE,
        KOCH_SNOWFLAKE,
        SIERPINSKI_TRIANGLE,
        DRAGON_CURVE
    }

    private Turtle tutel = null;
    private Graphics2D canvas = null;
    private final int scale;
    private final DrawingTarget drawingTarget;

    public MainPanel() {
        this(1, DrawingTarget.HOUSE);
    }

    public MainPanel(int scale) {
        this(scale, DrawingTarget.HOUSE);
    }

    public MainPanel(int scale, DrawingTarget drawingTarget) {
        this.scale = Math.max(1, scale);
        this.drawingTarget = drawingTarget == null ? DrawingTarget.HOUSE : drawingTarget;
    }

    @Override
    public void paint(Graphics g) {
        super.paint(g);

        this.tutel = new Turtle(this, g);
        this.canvas = g instanceof Graphics2D ? (Graphics2D) g : null;
        switch (drawingTarget) {
            case TREE:
                drawTree(scale);
                break;
            case Y_TREE:
                drawYTree(scale);
                break;
            case KOCH_SNOWFLAKE:
                drawKochSnowflake(scale);
                break;
            case SIERPINSKI_TRIANGLE:
                drawSierpinskiTriangle(scale);
                break;
            case DRAGON_CURVE:
                drawDragonCurve(scale);
                break;
            default:
                drawHouseOfNicholas(scale);
                break;
        }
    }

    public void drawHouseOfNicholas() {
        drawHouseOfNicholas(1);
    }

    public void drawHouseOfNicholas(int inputScale) {
        int normalizedScale = Math.max(1, inputScale);

        tutel.homePosition();

        // Original stroke order, with scalable line lengths.
        tutel.move(100 * normalizedScale);

        tutel.turnLeft(90);
        tutel.move(100 * normalizedScale);

        tutel.turnLeft(137);
        tutel.move(137 * normalizedScale);

        tutel.turnRight(137);
        tutel.move(100 * normalizedScale);

        tutel.turnRight(45);
        tutel.move(67 * normalizedScale);

        tutel.turnRight(90);
        tutel.move(66 * normalizedScale);

        tutel.turnRight(135);
        tutel.move(94 * normalizedScale);

        tutel.turnLeft(133);
        tutel.move(150 * normalizedScale);
    }

    public void drawTree(int inputScale) {
        int levels = clampLevel(inputScale, MAX_TREE_LEVELS);
        double trunkLength = moveToTreeStartAndDrawTrunk();
        double firstBranchLength = Math.max(35.0, trunkLength * (2.0 / 3.0));

        // Binary tree: each branch splits into two branches.
        drawBranchPair(firstBranchLength, levels - 1, BINARY_BRANCH_ANGLE, BINARY_BRANCH_SCALE);
    }

    public void drawYTree(int inputLevels) {
        int levels = clampLevel(inputLevels, MAX_Y_TREE_LEVELS);
        double trunkLength = moveToTreeStartAndDrawTrunk();
        double firstBranchLength = Math.max(35.0, trunkLength * 0.55);
        double firstStemLength = Math.max(30.0, trunkLength * 0.55);

        // Y-tree: each split creates two arms, and each arm grows a vertical stem before the next split.
        drawYTreeNode(firstBranchLength, firstStemLength, levels - 1);
    }

    private double moveToTreeStartAndDrawTrunk() {
        double panelHeight = Math.max(200.0, getHeight());
        double bottomMargin = 40.0;
        double trunkLength = Math.max(60.0, panelHeight / 4.0);

        tutel.homePosition();

        // Start near bottom-center, then face upward.
        tutel.stopDraw();
        tutel.turnRight(90);
        tutel.move((panelHeight / 2.0) - bottomMargin);
        tutel.turnLeft(180);
        tutel.startDraw();

        tutel.move(trunkLength);
        return trunkLength;
    }

    private void drawBranchPair(double branchLength, int extraLevels, double branchAngle, double shrinkFactor) {
        if (branchLength < 6.0) {
            return;
        }

        // Left branch from current heading.
        tutel.turnLeft(branchAngle);
        tutel.move(branchLength);
        if (extraLevels > 0) {
            drawBranchPair(branchLength * shrinkFactor, extraLevels - 1, branchAngle, shrinkFactor);
        }
        tutel.back(branchLength);

        // Right branch mirrored across the parent direction.
        tutel.turnRight(branchAngle * 2.0);
        tutel.move(branchLength);
        if (extraLevels > 0) {
            drawBranchPair(branchLength * shrinkFactor, extraLevels - 1, branchAngle, shrinkFactor);
        }
        tutel.back(branchLength);

        // Restore original heading before returning.
        tutel.turnLeft(branchAngle);
    }

    private void drawYTreeNode(double branchLength, double stemLength, int extraLevels) {
        if (branchLength < 6.0 || stemLength < 6.0 || extraLevels < 0) {
            return;
        }

        // Left arm from current split point.
        tutel.turnLeft(Y_BRANCH_ANGLE);
        tutel.move(branchLength);

        // Re-align to global up before drawing the next stem.
        tutel.turnRight(Y_BRANCH_ANGLE);
        tutel.move(stemLength);
        if (extraLevels > 0) {
            drawYTreeNode(branchLength * Y_BRANCH_SCALE, stemLength * Y_BRANCH_SCALE, extraLevels - 1);
        }
        tutel.back(stemLength);
        tutel.turnLeft(Y_BRANCH_ANGLE);
        tutel.back(branchLength);

        // Right arm mirrors the left arm from the same split point.
        tutel.turnRight(Y_BRANCH_ANGLE * 2.0);
        tutel.move(branchLength);

        // Re-align to global up before drawing the next stem.
        tutel.turnLeft(Y_BRANCH_ANGLE);
        tutel.move(stemLength);
        if (extraLevels > 0) {
            drawYTreeNode(branchLength * Y_BRANCH_SCALE, stemLength * Y_BRANCH_SCALE, extraLevels - 1);
        }
        tutel.back(stemLength);
        tutel.turnRight(Y_BRANCH_ANGLE);
        tutel.back(branchLength);

        // Restore original heading before returning.
        tutel.turnLeft(Y_BRANCH_ANGLE);
    }

    public void drawKochSnowflake(int inputLevels) {
        if (canvas == null) {
            return;
        }

        int levels = clampLevel(inputLevels, MAX_KOCH_LEVELS);
        double size = Math.min(getWidth(), getHeight()) * 0.35;
        if (size < 80) {
            size = 220;
        }

        double centerX = getWidth() / 2.0;
        double centerY = getHeight() / 2.0;
        double triHeight = size * Math.sqrt(3.0) / 2.0;

        double ax = centerX - (size / 2.0);
        double ay = centerY + (triHeight / 3.0);
        double bx = centerX + (size / 2.0);
        double by = ay;
        double cx = centerX;
        double cy = centerY - (2.0 * triHeight / 3.0);

        drawKochEdge(levels, ax, ay, bx, by);
        drawKochEdge(levels, bx, by, cx, cy);
        drawKochEdge(levels, cx, cy, ax, ay);
    }

    private void drawKochEdge(int level, double x1, double y1, double x5, double y5) {
        if (level <= 1) {
            drawLine(x1, y1, x5, y5);
            return;
        }

        double dx = (x5 - x1) / 3.0;
        double dy = (y5 - y1) / 3.0;

        double x2 = x1 + dx;
        double y2 = y1 + dy;
        double x4 = x1 + 2.0 * dx;
        double y4 = y1 + 2.0 * dy;

        // Rotate by -60 degrees to put the bump outside the base triangle.
        double cos60 = 0.5;
        double sin60 = Math.sqrt(3.0) / 2.0;
        double vx = x4 - x2;
        double vy = y4 - y2;
        double x3 = x2 + (vx * cos60 + vy * sin60);
        double y3 = y2 + (-vx * sin60 + vy * cos60);

        drawKochEdge(level - 1, x1, y1, x2, y2);
        drawKochEdge(level - 1, x2, y2, x3, y3);
        drawKochEdge(level - 1, x3, y3, x4, y4);
        drawKochEdge(level - 1, x4, y4, x5, y5);
    }

    public void drawSierpinskiTriangle(int inputLevels) {
        if (canvas == null) {
            return;
        }

        int levels = clampLevel(inputLevels, MAX_SIERPINSKI_LEVELS);
        double size = Math.min(getWidth(), getHeight()) * 0.6;
        if (size < 100) {
            size = 260;
        }

        double centerX = getWidth() / 2.0;
        double centerY = getHeight() / 2.0;
        double triHeight = size * Math.sqrt(3.0) / 2.0;

        double ax = centerX;
        double ay = centerY - (2.0 * triHeight / 3.0);
        double bx = centerX - (size / 2.0);
        double by = centerY + (triHeight / 3.0);
        double cx = centerX + (size / 2.0);
        double cy = by;

        drawSierpinskiRecursive(levels, ax, ay, bx, by, cx, cy);
    }

    private void drawSierpinskiRecursive(int level,
                                         double ax, double ay,
                                         double bx, double by,
                                         double cx, double cy) {
        if (level <= 1) {
            drawLine(ax, ay, bx, by);
            drawLine(bx, by, cx, cy);
            drawLine(cx, cy, ax, ay);
            return;
        }

        double abx = (ax + bx) / 2.0;
        double aby = (ay + by) / 2.0;
        double bcx = (bx + cx) / 2.0;
        double bcy = (by + cy) / 2.0;
        double cax = (cx + ax) / 2.0;
        double cay = (cy + ay) / 2.0;

        drawSierpinskiRecursive(level - 1, ax, ay, abx, aby, cax, cay);
        drawSierpinskiRecursive(level - 1, abx, aby, bx, by, bcx, bcy);
        drawSierpinskiRecursive(level - 1, cax, cay, bcx, bcy, cx, cy);
    }

    public void drawDragonCurve(int inputLevels) {
        int levels = clampLevel(inputLevels, MAX_DRAGON_LEVELS);
        double size = Math.min(getWidth(), getHeight()) * 0.45;
        if (size < 80) {
            size = 220;
        }

        tutel.homePosition();
        tutel.stopDraw();
        tutel.turnLeft(180);
        tutel.move(size / 2.0);
        tutel.turnRight(180);
        tutel.startDraw();

        drawDragonRecursive(levels, size, 1);
    }

    private void drawDragonRecursive(int level, double length, int sign) {
        if (level <= 1) {
            tutel.move(length);
            return;
        }

        double nextLength = length / Math.sqrt(2.0);
        drawDragonRecursive(level - 1, nextLength, 1);
        if (sign > 0) {
            tutel.turnLeft(90);
        } else {
            tutel.turnRight(90);
        }
        drawDragonRecursive(level - 1, nextLength, -1);
    }

    private int clampLevel(int input, int maxLevel) {
        return Math.min(maxLevel, Math.max(1, input));
    }

    private void drawLine(double x1, double y1, double x2, double y2) {
        if (canvas == null) {
            return;
        }

        canvas.drawLine(
                (int) Math.round(x1),
                (int) Math.round(y1),
                (int) Math.round(x2),
                (int) Math.round(y2)
        );
    }
}

package dev.kalarianathecila.schoolStuff.tutelini;

import java.awt.*;

public class MainPanel extends Panel {
    private static final int MAX_TREE_LEVELS = 12;
    private static final int MAX_Y_TREE_LEVELS = 12;
    private static final int MAX_KOCH_LEVELS = 6;
    private static final int MAX_SIERPINSKI_LEVELS = 7;
    private static final int MAX_DRAGON_LEVELS = 16;

    private static final double BINARY_BRANCH_ANGLE = 30.0;
    private static final double BINARY_BRANCH_SCALE = 0.7;
    private static final double Y_BRANCH_ANGLE = 35.0;
    private static final double Y_BRANCH_SCALE = 0.72;
    private static final double MIN_BRANCH_ANGLE = 1.0;
    private static final double MAX_BRANCH_ANGLE = 89.0;
    private static final double MIN_LENGTH_MULTIPLIER = 0.2;
    private static final double MAX_LENGTH_MULTIPLIER = 3.0;

    public enum DrawingTarget {
        HOUSE,
        TREE,
        Y_TREE,
        KOCH_SNOWFLAKE,
        SIERPINSKI_TRIANGLE,
        DRAGON_CURVE
    }

    private Turtle tutel = null;
    private Graphics2D canvas = null;
    private final int scale;
    private final DrawingTarget drawingTarget;
    private double treeAngleOffset = 0.0;
    private double treeLengthMultiplier = 1.0;

    public MainPanel() {
        this(1, DrawingTarget.HOUSE);
    }

    public MainPanel(int scale) {
        this(scale, DrawingTarget.HOUSE);
    }

    public MainPanel(int scale, DrawingTarget drawingTarget) {
        this.scale = Math.max(1, scale);
        this.drawingTarget = drawingTarget == null ? DrawingTarget.HOUSE : drawingTarget;
    }

    @Override
    public void paint(Graphics g) {
        super.paint(g);

        this.tutel = new Turtle(this, g);
        this.canvas = g instanceof Graphics2D ? (Graphics2D) g : null;
        switch (drawingTarget) {
            case TREE:
                drawTree(scale);
                break;
            case Y_TREE:
                drawYTree(scale);
                break;
            case KOCH_SNOWFLAKE:
                drawKochSnowflake(scale);
                break;
            case SIERPINSKI_TRIANGLE:
                drawSierpinskiTriangle(scale);
                break;
            case DRAGON_CURVE:
                drawDragonCurve(scale);
                break;
            default:
                drawHouseOfNicholas(scale);
                break;
        }
    }

    public void drawHouseOfNicholas() {
        drawHouseOfNicholas(1);
    }

    public void drawHouseOfNicholas(int inputScale) {
        int normalizedScale = Math.max(1, inputScale);

        tutel.homePosition();

        // Original stroke order, with scalable line lengths.
        tutel.move(100 * normalizedScale);

        tutel.turnLeft(90);
        tutel.move(100 * normalizedScale);

        tutel.turnLeft(137);
        tutel.move(137 * normalizedScale);

        tutel.turnRight(137);
        tutel.move(100 * normalizedScale);

        tutel.turnRight(45);
        tutel.move(67 * normalizedScale);

        tutel.turnRight(90);
        tutel.move(66 * normalizedScale);

        tutel.turnRight(135);
        tutel.move(94 * normalizedScale);

        tutel.turnLeft(133);
        tutel.move(150 * normalizedScale);
    }

    public void drawTree(int inputScale) {
        int levels = clampLevel(inputScale, MAX_TREE_LEVELS);
        double trunkLength = moveToTreeStartAndDrawTrunk(treeLengthMultiplier);
        double firstBranchLength = Math.max(35.0, trunkLength * (2.0 / 3.0));
        double branchAngle = clampDouble(BINARY_BRANCH_ANGLE + treeAngleOffset, MIN_BRANCH_ANGLE, MAX_BRANCH_ANGLE);

        // Binary tree: each branch splits into two branches.
        drawBranchPair(firstBranchLength, levels - 1, branchAngle, BINARY_BRANCH_SCALE);
    }

    public void drawYTree(int inputLevels) {
        int levels = clampLevel(inputLevels, MAX_Y_TREE_LEVELS);
        double trunkLength = moveToTreeStartAndDrawTrunk(treeLengthMultiplier);
        double firstBranchLength = Math.max(35.0, trunkLength * 0.55);
        double firstStemLength = Math.max(30.0, trunkLength * 0.55);
        double branchAngle = clampDouble(Y_BRANCH_ANGLE + treeAngleOffset, MIN_BRANCH_ANGLE, MAX_BRANCH_ANGLE);

        // Y-tree: each split creates two arms, and each arm grows a vertical stem before the next split.
        drawYTreeNode(firstBranchLength, firstStemLength, branchAngle, levels - 1);
    }

    private double moveToTreeStartAndDrawTrunk(double lengthMultiplier) {
        double panelHeight = Math.max(200.0, getHeight());
        double bottomMargin = 40.0;
        double trunkLength = Math.max(60.0, (panelHeight / 4.0) * lengthMultiplier);

        tutel.homePosition();

        // Start near bottom-center, then face upward.
        tutel.stopDraw();
        tutel.turnRight(90);
        tutel.move((panelHeight / 2.0) - bottomMargin);
        tutel.turnLeft(180);
        tutel.startDraw();

        tutel.move(trunkLength);
        return trunkLength;
    }

    private void drawBranchPair(double branchLength, int extraLevels, double branchAngle, double shrinkFactor) {
        if (branchLength < 6.0) {
            return;
        }

        // Left branch from current heading.
        tutel.turnLeft(branchAngle);
        tutel.move(branchLength);
        if (extraLevels > 0) {
            drawBranchPair(branchLength * shrinkFactor, extraLevels - 1, branchAngle, shrinkFactor);
        }
        tutel.back(branchLength);

        // Right branch mirrored across the parent direction.
        tutel.turnRight(branchAngle * 2.0);
        tutel.move(branchLength);
        if (extraLevels > 0) {
            drawBranchPair(branchLength * shrinkFactor, extraLevels - 1, branchAngle, shrinkFactor);
        }
        tutel.back(branchLength);

        // Restore original heading before returning.
        tutel.turnLeft(branchAngle);
    }

    private void drawYTreeNode(double branchLength, double stemLength, double branchAngle, int extraLevels) {
        if (branchLength < 6.0 || stemLength < 6.0 || extraLevels < 0) {
            return;
        }

        // Left arm from current split point.
        tutel.turnLeft(branchAngle);
        tutel.move(branchLength);

        // Re-align to global up before drawing the next stem.
        tutel.turnRight(branchAngle);
        tutel.move(stemLength);
        if (extraLevels > 0) {
            drawYTreeNode(branchLength * Y_BRANCH_SCALE, stemLength * Y_BRANCH_SCALE, branchAngle, extraLevels - 1);
        }
        tutel.back(stemLength);
        tutel.turnLeft(branchAngle);
        tutel.back(branchLength);

        // Right arm mirrors the left arm from the same split point.
        tutel.turnRight(branchAngle * 2.0);
        tutel.move(branchLength);

        // Re-align to global up before drawing the next stem.
        tutel.turnLeft(branchAngle);
        tutel.move(stemLength);
        if (extraLevels > 0) {
            drawYTreeNode(branchLength * Y_BRANCH_SCALE, stemLength * Y_BRANCH_SCALE, branchAngle, extraLevels - 1);
        }
        tutel.back(stemLength);
        tutel.turnRight(branchAngle);
        tutel.back(branchLength);

        // Restore original heading before returning.
        tutel.turnLeft(branchAngle);
    }

    public void adjustTreeAngle(double deltaDegrees) {
        treeAngleOffset = clampDouble(treeAngleOffset + deltaDegrees, -45.0, 45.0);
        repaint();
    }

    public void adjustTreeLengthMultiplier(double delta) {
        treeLengthMultiplier = clampDouble(treeLengthMultiplier + delta, MIN_LENGTH_MULTIPLIER, MAX_LENGTH_MULTIPLIER);
        repaint();
    }

    public double getTreeAngleOffset() {
        return treeAngleOffset;
    }

    public double getTreeLengthMultiplier() {
        return treeLengthMultiplier;
    }

    public void drawKochSnowflake(int inputLevels) {
        if (canvas == null) {
            return;
        }

        int levels = clampLevel(inputLevels, MAX_KOCH_LEVELS);
        double size = Math.min(getWidth(), getHeight()) * 0.35;
        if (size < 80) {
            size = 220;
        }

        double centerX = getWidth() / 2.0;
        double centerY = getHeight() / 2.0;
        double triHeight = size * Math.sqrt(3.0) / 2.0;

        double ax = centerX - (size / 2.0);
        double ay = centerY + (triHeight / 3.0);
        double bx = centerX + (size / 2.0);
        double by = ay;
        double cx = centerX;
        double cy = centerY - (2.0 * triHeight / 3.0);

        drawKochEdge(levels, ax, ay, bx, by);
        drawKochEdge(levels, bx, by, cx, cy);
        drawKochEdge(levels, cx, cy, ax, ay);
    }

    private void drawKochEdge(int level, double x1, double y1, double x5, double y5) {
        if (level <= 1) {
            drawLine(x1, y1, x5, y5);
            return;
        }

        double dx = (x5 - x1) / 3.0;
        double dy = (y5 - y1) / 3.0;

        double x2 = x1 + dx;
        double y2 = y1 + dy;
        double x4 = x1 + 2.0 * dx;
        double y4 = y1 + 2.0 * dy;

        // Rotate by -60 degrees to put the bump outside the base triangle.
        double cos60 = 0.5;
        double sin60 = Math.sqrt(3.0) / 2.0;
        double vx = x4 - x2;
        double vy = y4 - y2;
        double x3 = x2 + (vx * cos60 + vy * sin60);
        double y3 = y2 + (-vx * sin60 + vy * cos60);

        drawKochEdge(level - 1, x1, y1, x2, y2);
        drawKochEdge(level - 1, x2, y2, x3, y3);
        drawKochEdge(level - 1, x3, y3, x4, y4);
        drawKochEdge(level - 1, x4, y4, x5, y5);
    }

    public void drawSierpinskiTriangle(int inputLevels) {
        if (canvas == null) {
            return;
        }

        int levels = clampLevel(inputLevels, MAX_SIERPINSKI_LEVELS);
        double size = Math.min(getWidth(), getHeight()) * 0.6;
        if (size < 100) {
            size = 260;
        }

        double centerX = getWidth() / 2.0;
        double centerY = getHeight() / 2.0;
        double triHeight = size * Math.sqrt(3.0) / 2.0;

        double ax = centerX;
        double ay = centerY - (2.0 * triHeight / 3.0);
        double bx = centerX - (size / 2.0);
        double by = centerY + (triHeight / 3.0);
        double cx = centerX + (size / 2.0);
        double cy = by;

        drawSierpinskiRecursive(levels, ax, ay, bx, by, cx, cy);
    }

    private void drawSierpinskiRecursive(int level,
                                         double ax, double ay,
                                         double bx, double by,
                                         double cx, double cy) {
        if (level <= 1) {
            drawLine(ax, ay, bx, by);
            drawLine(bx, by, cx, cy);
            drawLine(cx, cy, ax, ay);
            return;
        }

        double abx = (ax + bx) / 2.0;
        double aby = (ay + by) / 2.0;
        double bcx = (bx + cx) / 2.0;
        double bcy = (by + cy) / 2.0;
        double cax = (cx + ax) / 2.0;
        double cay = (cy + ay) / 2.0;

        drawSierpinskiRecursive(level - 1, ax, ay, abx, aby, cax, cay);
        drawSierpinskiRecursive(level - 1, abx, aby, bx, by, bcx, bcy);
        drawSierpinskiRecursive(level - 1, cax, cay, bcx, bcy, cx, cy);
    }

    public void drawDragonCurve(int inputLevels) {
        int levels = clampLevel(inputLevels, MAX_DRAGON_LEVELS);
        double size = Math.min(getWidth(), getHeight()) * 0.45;
        if (size < 80) {
            size = 220;
        }

        tutel.homePosition();
        tutel.stopDraw();
        tutel.turnLeft(180);
        tutel.move(size / 2.0);
        tutel.turnRight(180);
        tutel.startDraw();

        drawDragonRecursive(levels, size, 1);
    }

    private void drawDragonRecursive(int level, double length, int sign) {
        if (level <= 1) {
            tutel.move(length);
            return;
        }

        double nextLength = length / Math.sqrt(2.0);
        drawDragonRecursive(level - 1, nextLength, 1);
        if (sign > 0) {
            tutel.turnLeft(90);
        } else {
            tutel.turnRight(90);
        }
        drawDragonRecursive(level - 1, nextLength, -1);
    }

    private int clampLevel(int input, int maxLevel) {
        return Math.min(maxLevel, Math.max(1, input));
    }

    private double clampDouble(double value, double minValue, double maxValue) {
        return Math.max(minValue, Math.min(maxValue, value));
    }

    private void drawLine(double x1, double y1, double x2, double y2) {
        if (canvas == null) {
            return;
        }

        canvas.drawLine(
                (int) Math.round(x1),
                (int) Math.round(y1),
                (int) Math.round(x2),
                (int) Math.round(y2)
        );
    }
}

